import React, { useEffect, useState } from "react";
import "./BudgetLimits.css";

function BudgetLimits({ onNext }) {

  const [categories, setCategories] = useState([]);
  const [limits, setLimits] = useState({});

  useEffect(() => {
    const user = JSON.parse(localStorage.getItem("user"));

    if (!user) return;

    // ✅ FETCH USER-SPECIFIC DATA
    const stored = JSON.parse(
      localStorage.getItem(`categories_${user.email}`)
    );

    if (stored && stored.length > 0) {
      setCategories(stored);
    }
  }, []);

  const handleChange = (cat, value) => {
    setLimits({
      ...limits,
      [cat]: value
    });
  };

  const handleNext = () => {
    const user = JSON.parse(localStorage.getItem("user"));

    if (!user) return;

    // ✅ SAVE LIMITS PER USER
    localStorage.setItem(
      `limits_${user.email}`,
      JSON.stringify(limits)
    );

    onNext();
  };

  return (
    <div className="budget-page">
      <h2>Set Budget Limits</h2>

      {categories.length === 0 ? (
        <p>No categories selected</p>
      ) : (
        categories.map((cat, i) => (
          <div key={i} className="budget-row">
            <label>{cat}</label>
            <input
              type="number"
              placeholder="Enter limit"
              onChange={(e) => handleChange(cat, e.target.value)}
            />
          </div>
        ))
      )}

      <button onClick={handleNext}>
        Save Limits
      </button>
    </div>
  );
}

export default BudgetLimits;
